    , #{insertNo}
    , NOW()
)

mapper.update:
/* AppLeaveFlowMapper.recomputeGrantUsedDays */
UPDATE TB_USER_LEAVE_GRANT G
   SET G.USED_DAYS = IFNULL((
           SELECT SUM(U.LEAVE_DAYS)
             FROM TB_USER_LEAVE_USE U
            WHERE U.CMPNY_CD     = G.CMPNY_CD
              AND U.GRANT_ID     = G.GRANT_ID
              AND U.LEAVE_STATUS = 'CONFIRMED'
              AND U.DEL_YN       = 'N'
       ), 0)
     , G.UPDATE_NO   = #{updateNo}
     , G.UPDATE_DATE = NOW()
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.GRANT_ID = #{grantId}

/* AppLeaveFlowMapper.updateReqStatus */
UPDATE TB_USER_ATTD_REQ
   SET REQ_STATUS      = #{reqStatus}
     , PROCESS_USER_CD = #{processUserCd}
     , PROCESS_COMMENT = #{processComment}
     , PROCESS_DATE    = NOW()
     , UPDATE_NO       = #{processUserCd}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND REQ_ID   = #{reqId}

mapper.insert:
/* AppLeaveFlowMapper.upsertWorkPlanLeave */
INSERT INTO TB_USER_WORK_PLAN (
      CMPNY_CD
    , SITE_CD
    , USER_CD
    , WORK_YMD
    , WORK_PLAN_CD
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{workYmd}
    , #{leaveCd}
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
      WORK_PLAN_CD = NEW.WORK_PLAN_CD
    , UPDATE_NO    = NEW.UPDATE_NO
    , UPDATE_DATE  = NOW()
